use super::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,turn:RetainedWorkOutcome)->RetainedCloneProgress{assert!(turn.work<=1);*fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;p}
#[test]
fn actual_typed_backing_is_retained_across_denial_null_initialization_and_uninitialized_cancel(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut owner=NativeOwnedStorage::<[u64;2]>::empty();assert_eq!(NativeOwnedStorage::<[u64;2]>::reserve_demand().capacity_bytes,row["bytes"].as_u64().unwrap()as usize);
 for denied in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:15,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.reserve(denied));assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert!(!owner.reserved());assert_eq!(post(&mut bank,&mut fuel,turn),Default::default());}
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.reserve(RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,row["nullWork"].as_u64().unwrap());fuel-=turn.work;assert_eq!(row["nullKind"],"AllocationFailed");assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert!(!owner.reserved());
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.reserve(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,row["reserveWork"].as_u64().unwrap());let p=post(&mut bank,&mut fuel,turn);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let address=owner.address();let mut input=Some([17,23]);let denied=owner.put_from(&mut input,RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,0);post(&mut bank,&mut fuel,denied);assert_eq!(input,Some([17,23]));assert_eq!(owner.address(),address);assert!(owner.get().is_none());
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.put_from(&mut input,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,row["initializeWork"].as_u64().unwrap());let p=post(&mut bank,&mut fuel,turn);assert_eq!(p.copied_bytes,row["initializeCopyBytes"].as_u64().unwrap()as usize);assert_eq!(heap,(0,0));assert!(input.is_none());assert_eq!(owner.address(),address);assert_eq!(serde_json::to_value(owner.get().unwrap()).unwrap(),row["value"]);
 let mut output=None;let turn=owner.take_into(&mut output,RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn);assert_eq!(output.take(),Some([17,23]));let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.release(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,row["releaseWork"].as_u64().unwrap());let p=post(&mut bank,&mut fuel,turn);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(owner.terminal_is_empty());assert_eq!(owner.release(Default::default()).work,row["cachedWork"].as_u64().unwrap());
 let turn=owner.reserve(RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn);assert!(owner.get().is_none());let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.release(RetainedCloneGrant{maximum_items:1,..bank}));let p=post(&mut bank,&mut fuel,turn);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(owner.terminal_is_empty());
}

